// Build-time loader for posts and research, which live in a separate GitHub repo
// (index.json generated by its GitHub Action, plus posts/*.md and research/*).
//
// Source, in order:
//   CONTENT_DIR=<folder>   a local checkout (e.g. CONTENT_DIR=website-info npm run build)
//   dev server             ./website-info if it exists
//   otherwise              CONTENT_URL, or raw.githubusercontent.com for site.contentRepo
import { existsSync } from "node:fs";
import { readFile } from "node:fs/promises";
import { resolve } from "node:path";
import { Marked, type Tokens } from "marked";
import { contentRawUrl, url } from "../data/site";

export interface PostEntry {
  slug: string;
  file: string;
  title: string;
  date: string;
  tags: string[];
  summary?: string;
  cover?: string;
}

export interface ResearchEntry {
  slug: string;
  file: string;
  title: string;
  summary: string;
  /** Key into RESEARCH_STATUS (e.g. "published", "preprint"); any other value is shown as written. */
  status: string;
  tags: string[];
  date?: string;
  venue?: string;
  /** Where the paper lives (e.g. ResearchGate); the row opens it in a new window. */
  url?: string;
  /** Repo path of the PDF, e.g. "research/minicollide.pdf", or a full URL. */
  pdf?: string;
  code?: string;
}

/** Label and badge style for each research status. Add a key here to support a new status. */
export const RESEARCH_STATUS: Record<string, { label: string; style: string }> = {
  published: { label: "Published", style: "bg-signal text-paper" },
  preprint: { label: "Preprint / Study protocol", style: "bg-ink text-paper" },
  ongoing: { label: "Ongoing", style: "bg-ink text-paper" },
  idea: { label: "Idea", style: "border border-ink" },
};

export function researchStatus(status: string) {
  return RESEARCH_STATUS[status.toLowerCase()] ?? { label: status, style: RESEARCH_STATUS.idea.style };
}

const SLUG = /^[a-z0-9][a-z0-9._-]*$/i;
export const isValidSlug = (slug: string | null | undefined): slug is string => !!slug && SLUG.test(slug);

export const postHref = (slug: string) => url(`/posts/${slug}/`);

const localDir = process.env.CONTENT_DIR
  ? resolve(process.env.CONTENT_DIR)
  : import.meta.env.DEV && existsSync(resolve("website-info"))
    ? resolve("website-info")
    : undefined;

const remoteBase = (() => {
  const b = process.env.CONTENT_URL ?? contentRawUrl("");
  return b.endsWith("/") ? b : `${b}/`;
})();

async function readText(path: string): Promise<string | null> {
  if (localDir) {
    const file = resolve(localDir, path);
    return file.startsWith(localDir) && existsSync(file) ? readFile(file, "utf8") : null;
  }
  const res = await fetch(new URL(path, remoteBase));
  if (res.status === 404) return null;
  if (!res.ok) throw new Error(`Could not load ${path} from ${remoteBase} (HTTP ${res.status})`);
  return res.text();
}

/** Public URL of a file in the content repo (cover images, images inside posts). */
export function assetUrl(path: string): string {
  // The dev server serves ./website-info at /__content/ (see astro.config.mjs).
  if (localDir && import.meta.env.DEV) return url(`/__content/${path}`);
  return new URL(path, localDir ? contentRawUrl("") : remoteBase).href;
}

/** YYYY-MM-DD of today in UTC. Posts dated after it are scheduled and left out of the build. */
const today = () => new Date().toISOString().slice(0, 10);
export const isScheduled = (p: { date: string }) =>
  process.env.INCLUDE_SCHEDULED !== "true" && p.date.slice(0, 10) > today();

const byDateDesc = (a: { date?: string }, b: { date?: string }) => ((a.date ?? "") < (b.date ?? "") ? 1 : -1);

let indexPromise: Promise<{ posts: PostEntry[]; research: ResearchEntry[] }> | undefined;

function loadIndex() {
  indexPromise ??= (async () => {
    const text = await readText("index.json");
    if (text === null) throw new Error(`index.json not found in ${localDir ?? remoteBase}`);
    const data = JSON.parse(text) as { posts?: PostEntry[]; research?: ResearchEntry[] };
    return {
      posts: (data.posts ?? []).filter((p) => isValidSlug(p.slug) && !isScheduled(p)).sort(byDateDesc),
      research: (data.research ?? []).filter((r) => isValidSlug(r.slug)).sort(byDateDesc),
    };
  })();
  return indexPromise;
}

/** Published posts, newest first (scheduled posts excluded). */
export async function getPosts(): Promise<PostEntry[]> {
  return (await loadIndex()).posts;
}

/** Research, newest first. */
export async function getResearch(): Promise<ResearchEntry[]> {
  return (await loadIndex()).research;
}

/** Strip the frontmatter block from a Markdown file. */
const stripFrontmatter = (md: string) => md.replace(/^---\r?\n[\s\S]*?\r?\n---\r?\n?/, "");

const isRelative = (v: string) => !/^([a-z][a-z0-9+.-]*:|\/\/|#|\/)/i.test(v);

/** Resolve a path relative to a file in the content repo, e.g. ("images/a.png", "posts/x.md") -> "posts/images/a.png". */
function repoPath(path: string, relativeTo: string): string {
  const resolved = new URL(path, new URL(relativeTo, "https://repo.invalid/")).pathname;
  return decodeURIComponent(resolved.slice(1));
}

/** Markdown -> HTML, with relative links/images pointed at the content repo and other posts. */
export function renderMarkdown(md: string, file: string): string {
  const marked = new Marked({
    gfm: true,
    walkTokens(token) {
      if (token.type !== "link" && token.type !== "image") return;
      const t = token as Tokens.Link | Tokens.Image;
      const post = t.href.match(/^(?:\.\/)?([^/]+)\.md$/);
      if (token.type === "link" && post && isValidSlug(post[1])) t.href = postHref(post[1]);
      else if (isRelative(t.href)) t.href = assetUrl(repoPath(t.href, file));
    },
    renderer: {
      link({ href, title, tokens }) {
        const text = this.parser.parseInline(tokens);
        // Internal links are base-relative paths, so any absolute http(s) link leaves the site.
        const attrs = [
          `href="${escapeHtml(href)}"`,
          title ? `title="${escapeHtml(title)}"` : "",
          /^https?:/i.test(href) ? `target="_blank" rel="noopener noreferrer"` : "",
        ].filter(Boolean);
        return `<a ${attrs.join(" ")}>${text}</a>`;
      },
      image({ href, title, text }) {
        return `<img src="${escapeHtml(href)}" alt="${escapeHtml(text)}"${title ? ` title="${escapeHtml(title)}"` : ""} loading="lazy" />`;
      },
    },
  });
  return marked.parse(stripFrontmatter(md), { async: false });
}

/** Full post with rendered HTML, or null if the file is missing. */
export async function getPost(entry: PostEntry) {
  const md = await readText(entry.file);
  if (md === null) return null;
  return { ...entry, html: renderMarkdown(md, entry.file) };
}

export function escapeHtml(s: string): string {
  return s.replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);
}

export function formatDate(iso: string): string {
  const d = new Date(`${iso.slice(0, 10)}T00:00:00Z`);
  return isNaN(d.getTime())
    ? iso
    : d.toLocaleDateString("en", { year: "numeric", month: "short", day: "numeric", timeZone: "UTC" });
}
